mapper.select:
SELECT v.owner_id,v.item_id,v.id AS version_id,v.version_number,v.title,v.body,
  i.owner_id AS item_owner_id,i.kind AS item_kind,i.status AS item_status
FROM knowledge_version v
LEFT JOIN knowledge_item i ON i.owner_id=v.owner_id AND i.id=v.item_id
WHERE v.owner_id=#{owner} AND v.item_id=#{itemId} AND v.id=#{versionId}
LIMIT #{limit}

SELECT d.owner_id,d.task_id,d.status,d.mode,d.target_item_id,d.target_version_id, t.owner_id AS task_owner_id,t.id AS actual_task_id,t.purpose,t.status AS task_status, t.manifest_json,t.manifest_hash,i.owner_id AS item_owner_id,i.id AS actual_item_id, i.kind AS item_kind,i.status AS item_status,v.owner_id AS version_owner_id,v.item_id AS version_item_id, v.id AS actual_version_id,v.version_number AS target_version_number, NULL AS target_project_id,NULL AS actual_project_id,t.created_at AS task_created_at FROM ai_candidate_decision d LEFT JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id LEFT JOIN knowledge_item i ON i.owner_id=d.owner_id AND i.id=d.target_item_id LEFT JOIN knowledge_version v ON v.owner_id=d.owner_id AND v.item_id=d.target_item_id AND v.id=d.target_version_id WHERE d.owner_id=#{owner} AND d.target_item_id=#{itemId}
AND (v.version_number <=#{through} OR v.id IS NULL OR v.version_number IS NULL)
AND d.task_id NOT IN #{id}
ORDER BY v.version_number,d.task_id LIMIT #{limit}

SELECT d.owner_id,d.task_id,d.status,d.mode,d.target_item_id,d.target_version_id, t.owner_id AS task_owner_id,t.id AS actual_task_id,t.purpose,t.status AS task_status, t.manifest_json,t.manifest_hash,i.owner_id AS item_owner_id,i.id AS actual_item_id, i.kind AS item_kind,i.status AS item_status,v.owner_id AS version_owner_id,v.item_id AS version_item_id, v.id AS actual_version_id,v.version_number AS target_version_number, NULL AS target_project_id,i.project_id AS actual_project_id,t.created_at AS task_created_at FROM ai_expression_decision d LEFT JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id LEFT JOIN preparation_item i ON i.owner_id=d.owner_id AND i.id=d.target_item_id LEFT JOIN preparation_version v ON v.owner_id=d.owner_id AND v.item_id=d.target_item_id AND v.id=d.target_version_id WHERE d.owner_id=#{owner} AND d.target_item_id=#{itemId} AND (v.version_number <=#{through} OR v.id IS NULL OR v.version_number IS NULL)
AND d.task_id NOT IN #{id}
ORDER BY v.version_number,d.task_id LIMIT #{limit}

SELECT d.owner_id,d.task_id,d.status,NULL AS mode,d.target_item_id,d.target_version_id, t.owner_id AS task_owner_id,t.id AS actual_task_id,t.purpose,t.status AS task_status, t.manifest_json,t.manifest_hash,i.owner_id AS item_owner_id,i.id AS actual_item_id, i.kind AS item_kind,i.status AS item_status,v.owner_id AS version_owner_id,v.item_id AS version_item_id, v.id AS actual_version_id,v.version_number AS target_version_number, d.target_project_id,i.project_id AS actual_project_id,t.created_at AS task_created_at FROM ai_fact_draft_decision d LEFT JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id LEFT JOIN preparation_item i ON i.owner_id=d.owner_id AND i.id=d.target_item_id LEFT JOIN preparation_version v ON v.owner_id=d.owner_id AND v.item_id=d.target_item_id AND v.id=d.target_version_id WHERE d.owner_id=#{owner} AND d.target_item_id=#{itemId} AND (v.version_number <=#{through} OR v.id IS NULL OR v.version_number IS NULL)
AND d.task_id NOT IN #{id}
ORDER BY v.version_number,d.task_id LIMIT #{limit}

SELECT owner_id,task_id,source_item_id AS item_id,source_version_id AS version_id,
  source_version_number AS version_number,source_title AS title,ordinal
FROM ai_knowledge_source
WHERE owner_id=#{owner} AND task_id=#{taskId}
ORDER BY ordinal,source_item_id,source_version_id LIMIT #{limit}

SELECT d.owner_id,d.task_id,d.status,NULL AS mode,d.target_question_id AS target_item_id,d.target_version_id, t.owner_id AS task_owner_id,t.id AS actual_task_id,t.purpose,t.status AS task_status, t.manifest_json,t.manifest_hash,q.owner_id AS item_owner_id,q.id AS actual_item_id, 'QUESTION' AS item_kind,q.status AS item_status,v.owner_id AS version_owner_id,v.question_id AS version_item_id, v.id AS actual_version_id,v.version_number AS target_version_number, NULL AS target_project_id,NULL AS actual_project_id,t.created_at AS task_created_at FROM ai_question_decision d LEFT JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id LEFT JOIN question q ON q.owner_id=d.owner_id AND q.id=d.target_question_id LEFT JOIN question_version v ON v.owner_id=d.owner_id AND v.question_id=d.target_question_id AND v.id=d.target_version_id WHERE d.owner_id=#{owner} AND d.target_question_id=#{itemId} AND (v.version_number <=#{through} OR v.id IS NULL OR v.version_number IS NULL)
AND d.task_id NOT IN #{id}
ORDER BY v.version_number,d.task_id LIMIT #{limit}

SELECT owner_id,task_id,source_item_id AS item_id,source_version_id AS version_id,
  source_version_number AS version_number,source_title AS title,ordinal
FROM ai_question_source
WHERE owner_id=#{owner} AND task_id=#{taskId}
ORDER BY ordinal,source_item_id,source_version_id LIMIT #{limit}

SELECT owner_id,task_id,source_item_id AS item_id,source_version_id AS version_id,
  source_kind AS kind,source_version_number AS version_number,source_title AS title,ordinal
FROM ai_preparation_source
WHERE owner_id=#{owner} AND task_id=#{taskId}
ORDER BY ordinal,source_item_id,source_version_id LIMIT #{limit}

SELECT owner_id,task_id,kind,session_id,question_id,answer_id
FROM ai_fact_draft_source
WHERE owner_id=#{owner} AND task_id=#{taskId}
ORDER BY task_id LIMIT #{limit}

SELECT owner_id,task_id,session_id,question_id,answer_id,evaluation_task_id
FROM ai_training_draft_source
WHERE owner_id=#{owner} AND task_id=#{taskId}
ORDER BY task_id LIMIT #{limit}

SELECT owner_id,session_id,question_id,answer_id,knowledge_item_id AS item_id,knowledge_version_id AS version_id
FROM training_answer_knowledge_reference

WHERE owner_id=#{owner} AND answer_id=#{answerId}
ORDER BY knowledge_item_id,knowledge_version_id,session_id,question_id LIMIT #{limit}

SELECT v.owner_id,v.question_id,v.id AS version_id,v.version_number,v.title,v.prompt_json,
  q.owner_id AS item_owner_id,q.id AS actual_question_id,q.status AS item_status
FROM question_version v
LEFT JOIN question q ON q.owner_id=v.owner_id AND q.id=v.question_id
WHERE v.owner_id=#{owner} AND v.question_id=#{itemId} AND v.id=#{versionId}
LIMIT #{limit}

SELECT owner_id,session_id,question_id,knowledge_item_id AS item_id,knowledge_version_id AS version_id
FROM training_question_knowledge_snapshot

WHERE owner_id=#{owner} AND question_id=#{questionId}
ORDER BY knowledge_item_id,knowledge_version_id,session_id LIMIT #{limit}

SELECT owner_id,question_id,version_id,knowledge_item_id,knowledge_version_id,position_index
FROM question_knowledge_reference

WHERE owner_id=#{owner} AND version_id=#{versionId}
ORDER BY position_index,knowledge_item_id,knowledge_version_id,question_id LIMIT #{limit}

SELECT v.owner_id,v.question_id,v.id AS version_id,v.standard_status,v.reference_answer,v.checkpoints_json,
  q.owner_id AS item_owner_id,q.id AS actual_question_id
FROM question_version v
LEFT JOIN question q ON q.owner_id=v.owner_id AND q.id=v.question_id
WHERE v.owner_id=#{owner} AND v.question_id=#{itemId} AND v.id=#{versionId}
LIMIT #{limit}

SELECT a.owner_id,a.id AS answer_id,a.session_id,a.question_id,s.owner_id AS session_owner_id,
  s.id AS actual_session_id,s.status AS session_status
FROM training_answer a
LEFT JOIN training_session s ON s.owner_id=a.owner_id AND s.id=a.session_id

WHERE a.owner_id=#{owner} AND a.id=#{answerId}
LIMIT #{limit}

SELECT v.owner_id,v.recollection_id,v.id AS version_id,v.version_number,v.title,v.baseline_kind,v.content_json,
  r.owner_id AS item_owner_id,r.id AS actual_item_id,r.status AS item_status
FROM review_recollection_version v
LEFT JOIN review_recollection r ON r.owner_id=v.owner_id AND r.id=v.recollection_id
WHERE v.owner_id=#{owner} AND v.recollection_id=#{itemId} AND v.id=#{versionId}
LIMIT #{limit}
